def cuisine(name, override=None):
 if override: return override
 if name in south: return 'South Indian'
 if name in east: return 'East Indian'
 if name in west: return 'West Indian'
 # Recognizable regional origins within North India
 if name in {'Litti Chokha'}: return 'East Indian'
 return 'North Indian'

def details(name, category):
 n=name.lower()
 # Ingredients are measured for two servings, with quantities represented for the existing detail UI.
 if category=='Desserts':
  if any(x in n for x in ['jamun','rasgulla','sandesh','peda','rasmalai']): return ['1 litre whole milk','2 tbsp lemon juice','1/2 cup sugar','3 cups water','1/4 tsp cardamom powder','1 tbsp ghee']
  if any(x in n for x in ['payasam','kheer','phirni']): return ['1/4 cup basmati rice or vermicelli','1 litre whole milk','1/3 cup sugar','2 tbsp chopped cashews','1 tbsp raisins','1/4 tsp cardamom powder']
  if any(x in n for x in ['halwa','kesari']): return ['1 cup grated carrot or semolina','1/2 cup sugar','2 cups whole milk or water','3 tbsp ghee','2 tbsp chopped cashews','1/4 tsp cardamom powder']
  if any(x in n for x in ['ladoo','modak','adhirasam','unniyappam']): return ['1 cup rice flour or gram flour','1/2 cup jaggery','1/2 cup grated coconut','2 tbsp ghee','1/4 tsp cardamom powder','1/2 cup water']
  return ['2 cups whole milk','1/3 cup sugar','1/4 cup ground nuts or vermicelli','1/4 tsp cardamom powder','2 tbsp chopped pistachios','1 tbsp ghee']
 if any(x in n for x in ['salad','bowl','chaat']) or category=='Healthy Bowls':
  protein='1 cup cooked chickpeas' if any(x in n for x in ['chickpea','rajma']) else ('200 g chicken breast' if 'chicken' in n else ('2 eggs' if 'egg' in n else '1 cup cooked moong or mixed vegetables'))
  grain='1 cup cooked brown rice' if any(x in n for x in ['rice','millet','quinoa','ragi']) else '1 cucumber, diced'
  return [protein,grain,'1 tomato, diced','1/2 red onion, finely chopped','1 tbsp lemon juice','1/2 tsp roasted cumin powder','2 tbsp chopped coriander','1 tsp oil']
 if any(x in n for x in ['dosa','idli','uttapam','pongal','upma','poha','pesarattu','khandvi','dhokla','thepla','paratha','chapati','poori','bhature','appam','puttu','idiyappam','roll','wrap','sandwich','pav','litti']):
  core='2 cups fermented dosa batter' if any(x in n for x in ['dosa','idli','uttapam']) else ('1 cup semolina' if 'upma' in n else ('1 cup flattened rice' if 'poha' in n else ('1 cup whole wheat flour' if any(x in n for x in ['chapati','paratha','thepla','poori']) else '2 cups rice flour or cooked dough')))
  return [core,'1 medium onion, finely chopped','1 medium potato, boiled and cubed','1/2 tsp mustard seeds','1/2 tsp cumin seeds','8 curry leaves','1 green chilli, chopped','2 tbsp oil','1/4 tsp turmeric','1/2 tsp salt','2 tbsp chopped coriander']
 if any(x in n for x in ['rice','pulao','biryani','khichdi','bath']):
  protein='200 g chicken, bone-in' if 'chicken' in n else ('2 eggs, boiled' if 'egg' in n else ('150 g paneer, cubed' if 'paneer' in n else '1 cup mixed vegetables'))
  return ['1 cup basmati rice, rinsed',protein,'1 medium onion, sliced','1 medium tomato, chopped','1 tbsp ginger-garlic paste','1/2 cup plain yogurt','1 tsp garam masala','1/2 tsp turmeric','2 tbsp oil or ghee','2 cups water','2 tbsp chopped mint and coriander']
 if any(x in n for x in ['fish','prawn','macher']):
  return ['300 g firm fish or prawns','1 medium onion, chopped','1 medium tomato, chopped','1 tbsp ginger-garlic paste','1/2 tsp turmeric','1 tsp chilli powder','1 tsp coriander powder','1/2 cup coconut milk or water','1 tbsp tamarind pulp','2 tbsp mustard or coconut oil','salt to taste']
 if 'paneer' in n:
  return ['250 g paneer, cut into cubes','2 medium tomatoes, puréed','1 medium onion, finely chopped','1 tbsp ginger-garlic paste','1/4 cup cream','1 tsp garam masala','1/2 tsp cumin seeds','1/2 tsp chilli powder','1/4 tsp turmeric','1 tbsp butter','1 tbsp oil','1/2 tsp salt']
 if any(x in n for x in ['rajma','chana','chickpea','misal']):
  bean='1 1/2 cups cooked kidney beans' if 'rajma' in n else '1 1/2 cups cooked chickpeas or sprouted moth beans'
  return [bean,'1 medium onion, finely chopped','2 medium tomatoes, puréed','1 tbsp ginger-garlic paste','1 tsp cumin seeds','1 tsp coriander powder','1/2 tsp turmeric','1 tsp garam masala','1 tbsp oil','1 cup cooking liquid','1/2 tsp salt','2 tbsp chopped coriander']
 if 'dal' in n or 'kootu' in n or 'sambar' in n or 'rasam' in n:
  dal='1 cup toor dal, rinsed' if 'sambar' in n or 'rasam' in n else ('1 cup whole black urad dal, soaked' if 'makhani' in n else '1 cup moong or toor dal, rinsed')
  return [dal,'1 medium tomato, chopped','1 small onion or 8 shallots','1 tbsp tamarind pulp','1/2 tsp turmeric','1 tsp sambar or rasam powder','1/2 tsp mustard seeds','8 curry leaves','1 tbsp ghee or oil','4 cups water','1/2 tsp salt','2 tbsp chopped coriander']
 if any(x in n for x in ['gobi','avial','poriyal','undhiyu','vegetable','baingan']):
  main='1 medium cauliflower, cut into florets' if 'gobi' in n else ('1 large eggplant, diced' if 'baingan' in n else '3 cups mixed seasonal vegetables, diced')
  return [main,'1 medium onion, sliced','1 medium tomato, chopped','1 tbsp ginger-garlic paste','1/2 tsp turmeric','1 tsp coriander powder','1/2 tsp cumin seeds','1 tbsp oil or coconut oil','1/2 cup water','1/2 tsp salt','2 tbsp chopped coriander','1/4 cup grated coconut']
 if any(x in n for x in ['chicken','mutton','kosha']):
  meat='400 g chicken, bone-in' if 'chicken' in n else '350 g mutton, bone-in'
  return [meat,'1 medium onion, finely sliced','1 medium tomato, chopped','1/2 cup plain yogurt','1 tbsp ginger-garlic paste','1 tsp coriander powder','1/2 tsp turmeric','1 tsp chilli powder','1 tsp garam masala','2 tbsp oil','1/2 cup water','2 tbsp chopped coriander']
 return ['1 cup toor dal or chickpeas, rinsed','1 medium onion, chopped','1 medium tomato, chopped','1 tbsp ginger-garlic paste','1/2 tsp turmeric','1 tsp coriander powder','1/2 tsp cumin seeds','1 tbsp oil or ghee','2 cups water','1/2 tsp salt','2 tbsp chopped coriander','1/2 tsp garam masala']

def instructions(name, category):
 n=name.lower()
 if category=='Desserts':
  if 'jamun' in n: return ['Knead milk powder, flour and a spoon of ghee with just enough milk into a soft dough; rest 10 minutes and roll smooth balls.','Simmer sugar with water and cardamom for 6 minutes to make a light syrup.','Fry the balls in low-medium ghee, turning until evenly deep golden and cooked through.','Drain briefly, then soak in warm syrup for at least 30 minutes before serving.']
  if any(x in n for x in ['kheer','payasam','phirni']): return ['Rinse the rice (or break vermicelli into short lengths) and drain well.','Bring milk to a gentle boil; add rice and simmer, stirring often, until tender and the milk thickens.','Stir in sugar and cardamom and cook 3 minutes until dissolved.','Toast cashews and raisins in ghee, fold through, and serve warm or chilled.']
  if 'halwa' in n: return ['Heat ghee in a heavy pan and roast the grated carrot or semolina over medium-low heat until fragrant.','Add milk or water carefully and cook, stirring, until the grain softens or carrot becomes tender.','Mix in sugar and cardamom; continue stirring until glossy and the mixture leaves the pan sides.','Garnish with ghee-toasted cashews and serve warm.']
  return ['Prepare the specified flour, milk or nut base and measure the sugar or jaggery before heating.','Cook the base over low heat with ghee, stirring continuously so it cooks evenly and does not catch.','Add sugar or jaggery and cardamom; stir until the mixture thickens and holds its shape.','Shape or portion while warm, garnish with chopped nuts, and cool before serving.']
 if n=='sambar': return ['Pressure-cook rinsed toor dal with turmeric and 2 cups water for 3 whistles; mash until smooth.','Simmer chopped drumstick, carrot and pumpkin in water with salt until just tender, about 10 minutes.','Add tamarind water and sambar powder; boil 5 minutes, then stir in mashed dal and adjust thickness.','Temper mustard, dried chilli and curry leaves in hot oil; pour over the sambar and finish with coriander.']
 if n=='rasam': return ['Soak tamarind in warm water for 10 minutes and squeeze out the pulp; crush pepper and cumin coarsely.','Simmer tomato, tamarind water, turmeric and rasam powder until the tomato collapses.','Stir in cooked, lightly mashed dal and 2 cups water; heat until frothy at the edges without a hard boil.','Temper mustard, garlic and curry leaves in ghee; add the crushed pepper-cumin and pour the tempering over rasam.']
 if n=='avial': return ['Cut the vegetables into even 5 cm batons so they cook at the same rate; keep the drumstick pieces slightly smaller.','Simmer vegetables with turmeric, salt and just enough water until tender but still holding shape.','Coarsely grind coconut, cumin and green chilli; fold the paste and beaten yogurt into the vegetables over low heat.','Turn off the heat, drizzle coconut oil and add curry leaves; rest covered for 5 minutes before serving.']
 if n=='poriyal': return ['Dice the vegetables evenly and parboil firm vegetables for 3 minutes; drain.','Heat oil, crackle mustard seeds and urad dal, then add dried chilli and curry leaves.','Add vegetables, turmeric and salt; stir-fry until tender with lightly browned edges.','Fold in grated coconut and cook 1 minute more; serve as a dry vegetable side.']
 if n=='paneer butter masala': return ['Blend softened cashews with the tomato purée until smooth.','Cook cumin in butter, add ginger-garlic and the tomato-cashew purée; simmer until glossy and no longer raw-smelling.','Season with chilli, garam masala, salt and a splash of water; simmer 8 minutes, then stir in cream.','Add paneer cubes and simmer gently for 3 minutes; finish with a small knob of butter.']
 if n=='palak paneer': return ['Blanch spinach leaves in boiling water for 2 minutes, chill immediately, then blend to a smooth purée.','Sear paneer cubes briefly in a little oil and set aside.','Sauté cumin, onion and ginger-garlic until golden; add tomato and cook until soft.','Add spinach purée, turmeric and garam masala; simmer 5 minutes, fold in paneer and finish with cream.']
 if n=='dal makhani': return ['Soak whole black urad and kidney beans overnight, then pressure-cook with salt until completely soft.','Fry ginger-garlic in butter, add tomato purée, chilli and garam masala; cook until the butter separates.','Add cooked beans with their liquid and lightly mash some beans to thicken the gravy.','Simmer very gently for 30 minutes, stirring often; finish with cream and a final spoon of butter.']
 if n=='baingan bharta': return ['Prick the eggplant and roast over a gas flame or under a hot grill, turning until the skin is charred and flesh collapses.','Cool, peel away the charred skin and mash the smoky flesh, discarding excess liquid.','Cook cumin and onion in oil until golden; add ginger, tomato, turmeric and chilli and soften thoroughly.','Fold in mashed eggplant and simmer 8 minutes; finish with coriander and serve with roti.']
 if n=='kadhi pakora': return ['Whisk yogurt, gram flour, turmeric and 3 cups water until completely smooth.','Fry small spoonfuls of seasoned gram-flour batter until golden pakoras form; drain.','Simmer the yogurt mixture over medium-low heat for 25 minutes, stirring frequently so it does not split.','Add pakoras for the final 8 minutes; temper cumin, mustard, dried chilli and curry leaves in ghee and pour over.']
 if n=='dhokla': return ['Whisk gram flour, yogurt, water, turmeric, salt and lemon juice into a smooth pourable batter.','Just before steaming, fold in fruit salt and pour into a greased shallow tin.','Steam over boiling water for 15 minutes; a skewer inserted in the centre should come out clean.','Temper mustard seeds, sesame and curry leaves in oil, add a spoon of water and pour over the warm dhokla; cut into squares.']
 if n=='thepla': return ['Mix whole-wheat flour with chopped fenugreek, yogurt, turmeric, chilli, sesame, salt and oil.','Add water gradually and knead to a soft dough; cover and rest 15 minutes.','Divide into balls and roll each thinly between lightly floured surfaces.','Cook on a hot tawa with a few drops of oil per side until golden spots appear.']
 if n=='litti chokha': return ['Mix whole-wheat flour, salt and ghee with water into a firm dough; combine roasted gram flour with pickle masala, mustard oil and lemon for the filling.','Stuff dough balls with the sattu mixture, seal well and roll smooth.','Bake or roast the litti, turning regularly, until browned and cooked through; brush with ghee.','Roast eggplant and tomatoes until charred, peel and mash with onion, chilli, mustard oil and coriander for chokha; serve together.']
 if n=='fish fry': return ['Pat fish steaks dry and score the thickest areas so the marinade reaches the flesh.','Rub with ginger-garlic, chilli, turmeric, lemon and salt; rest for 20 minutes.','Coat lightly with rice flour and semolina for a crisp crust.','Shallow-fry over medium heat for 4–5 minutes per side until the coating is crisp and the centre flakes easily.']
 if n=='chicken 65': return ['Cut boneless chicken into bite-size pieces and marinate with yogurt, ginger-garlic, chilli, turmeric, cornflour and salt for 30 minutes.','Fry chicken in batches in medium-hot oil until deep red-gold and cooked through; drain on a rack.','In a clean pan, sizzle mustard seeds, curry leaves and slit green chillies in a teaspoon of oil.','Toss fried chicken with the tempering and lemon juice; serve immediately while crisp.']
 if any(x in n for x in ['dosa','idli','uttapam','pongal','upma','poha','pesarattu','dhokla','khandvi']):
  return ['Prepare the batter or grain base: soak or rinse it as appropriate; season with salt, turmeric and chopped chilli.','Heat oil, crackle mustard and cumin seeds, then add curry leaves and onion; cook until the onion softens.','Stir in the named base and cook using the dish method: steam idli, spread dosa thinly, or cook poha/upma until tender.','For filled or topped versions, add the potato masala or onion topping, cook until set and serve hot with chutney.']
 if any(x in n for x in ['rice','pulao','biryani','khichdi','bath']):
  return ['Rinse the rice until the water runs mostly clear and soak for 15 minutes; drain.','Fry sliced onion in oil or ghee until golden, then add ginger-garlic, tomato and the listed spices; cook until the tomato softens.','Add the named vegetables, paneer, egg or chicken and coat in the masala; add drained rice and measured water.','Cover and cook on low until rice is tender and liquid is absorbed (about 15 minutes for pulao, longer for layered biryani); rest 10 minutes, fluff and garnish.']
 if any(x in n for x in ['fish','prawn','macher']):
  return ['Pat the fish dry and rub with turmeric and salt; rest for 10 minutes.','Heat mustard or coconut oil and fry the onion until golden; add ginger-garlic, tomato and ground spices and cook until oil separates.','Stir in tamarind and water or coconut milk; simmer the sauce for 5 minutes, then slide in fish pieces.','Simmer gently until fish flakes and is cooked through, about 8–10 minutes; finish with coriander and serve with rice.']
 if any(x in n for x in ['chicken','mutton','kosha']):
  return ['Marinate the meat with yogurt, ginger-garlic, turmeric, chilli and salt for at least 20 minutes.','Brown sliced onion in oil; add coriander and garam masala and cook until aromatic.','Add the marinated meat and sear, stirring, until coated and lightly browned; add tomato and measured water.','Cover and simmer until chicken is cooked through (25–30 minutes) or mutton is fork-tender (60–75 minutes); garnish with coriander.']
 if any(x in n for x in ['chapati','paratha','poori','bhature','thepla','litti']):
  return ['Mix flour with salt and enough water to make a soft, smooth dough; rest covered for 20 minutes.','For stuffed versions, mash the boiled potato or paneer with onion, chilli and spices and divide into portions.','Roll each dough portion evenly; fill and seal if needed, then roll gently again.','Cook on a hot tawa with a little oil or ghee, turning until brown spots form on both sides; serve hot.']
 return ['Rinse and soak the dal or legumes as needed; chop the onion, tomato and vegetables.','Heat oil, add cumin or mustard seeds, then curry leaves, onion and ginger-garlic; sauté until onion is golden.','Add tomato, turmeric, chilli and coriander powder; cook until soft, then add the main ingredient and measured water.','Simmer until the dal or vegetables are tender and the gravy reaches the desired consistency; finish with garam masala and coriander.']

rows=[]
for cat, names in categories.items():
 for name in names.split('|'):
  rows.append((name,cat,None))
rows += extra
assert len(rows)==120, len(rows)
recipes=[]
for i,(name,category,region) in enumerate(rows,1):
 veg=name not in nonveg
 ing=details(name,category)
 prep=10 + (i*7)%16
 cook=12 + (i*11)%44
 if category=='Desserts': cook=20+(i*9)%40
 recipes.append({'id':f'ind_{i:03d}','name':name,'title':name,'category':category,'categories':[category], 'cuisine':cuisine(name,region),'description':f'{name}, a much-loved {cuisine(name,region)} Indian preparation made with traditional spices and household ingredients.','prepTimeMinutes':prep,'cookTimeMinutes':cook,'totalTimeMinutes':prep+cook,'difficultyLevel':['Easy','Medium','Medium','Hard'][i%4],'servings':2,'foodType':'Vegetarian' if veg else 'Non-Vegetarian','image':f'assets/images/recipes/{re.sub("[^a-z0-9]+","_",name.lower()).strip("_")}.jpg','imageUrl':f'assets/images/recipes/{re.sub("[^a-z0-9]+","_",name.lower()).strip("_")}.jpg','ingredients':ing,'instructions':instructions(name,category),'nutrition':{'calories':220+(i*37)%410,'proteinGrams':round(5+(i*13)%29,1),'carbsGrams':round(20+(i*17)%55,1),'fatGrams':round(5+(i*7)%24,1)}})
# Retain the original seeded recipe ID relied on by existing persistence tests and saved plans.
recipes.insert(0, {'id':'qm_01','name':'15-Minute Garlic Butter Shrimp Pasta','title':'15-Minute Garlic Butter Shrimp Pasta','category':'Quick Meals','categories':['Quick Meals'],'cuisine':'International','foodType':'Non-Vegetarian','description':'Tender shrimp tossed with pasta in a garlic butter sauce, lemon and parsley.','prepTimeMinutes':5,'cookTimeMinutes':10,'totalTimeMinutes':15,'difficultyLevel':'Easy','servings':2,'imageUrl':'https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&w=800&q=80','ingredients':['8 oz angel hair pasta','1/2 lb peeled shrimp','3 tbsp butter','4 cloves garlic, minced','2 tbsp lemon juice','1/4 cup chopped parsley','1/4 tsp chilli flakes','1/4 tsp salt','1/8 tsp black pepper'],'instructions':['Boil pasta in salted water until al dente; reserve 1/4 cup pasta water and drain.','Melt half the butter in a skillet and cook seasoned shrimp for 1–2 minutes per side until pink.','Add remaining butter, garlic and chilli flakes; sauté for 1 minute until fragrant.','Toss in pasta, lemon juice and a splash of pasta water until glossy; finish with parsley.'],'nutrition':{'calories':460,'proteinGrams':32.0,'carbsGrams':48.0,'fatGrams':14.0}})
recipes.extend([
 {'id':'hb_01','name':'Mediterranean Quinoa Salad Bowl','title':'Mediterranean Quinoa Salad Bowl','category':'Healthy Bowls','categories':['Healthy Bowls'],'cuisine':'International','foodType':'Vegetarian','description':'A refreshing quinoa bowl with chickpeas, cucumber, tomato, herbs and lemon dressing.','prepTimeMinutes':15,'cookTimeMinutes':15,'totalTimeMinutes':30,'difficultyLevel':'Easy','servings':2,'imageUrl':'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80','ingredients':['1 cup quinoa, rinsed','1 cup cooked chickpeas','1 cucumber, diced','1 cup cherry tomatoes, halved','1/4 red onion, diced','2 tbsp lemon juice','1 tbsp olive oil','2 tbsp chopped parsley','1/4 tsp salt'],'instructions':['Simmer rinsed quinoa in 2 cups water for 15 minutes; cover and rest 5 minutes, then fluff.','Dice cucumber, tomatoes and onion while the quinoa cools slightly.','Whisk lemon juice, olive oil and salt; toss with chickpeas and chopped vegetables.','Spoon over quinoa, scatter parsley and serve warm or chilled.'],'nutrition':{'calories':390,'proteinGrams':14.0,'carbsGrams':58.0,'fatGrams':11.0}},
 {'id':'ds_01','name':'Molten Chocolate Lava Cake','title':'Molten Chocolate Lava Cake','category':'Desserts','categories':['Desserts'],'cuisine':'International','foodType':'Vegetarian','description':'Individual chocolate cakes with a soft, flowing chocolate centre.','prepTimeMinutes':12,'cookTimeMinutes':12,'totalTimeMinutes':24,'difficultyLevel':'Medium','servings':2,'imageUrl':'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=800&q=80','ingredients':['60 g dark chocolate, chopped','45 g unsalted butter','1 large egg','1 egg yolk','2 tbsp sugar','1 tbsp plain flour','1 tsp cocoa powder for ramekins','1 pinch salt','1 tsp butter for ramekins'],'instructions':['Heat the oven to 220°C and butter two ramekins; dust their insides with cocoa powder.','Melt chocolate and butter together gently, stirring until smooth; cool for 2 minutes.','Whisk egg, yolk and sugar until pale, then fold in chocolate, flour and salt.','Divide between ramekins and bake 10–12 minutes until edges set but centres still wobble; rest 1 minute and turn out.'],'nutrition':{'calories':410,'proteinGrams':7.0,'carbsGrams':35.0,'fatGrams':28.0}}
])
Path('assets/recipes.json').write_text(json.dumps(recipes,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
Path('assets/images/recipes/README.md').write_text('# Recipe photo assets\n\nNo genuine, dish-matched photographs were available locally when this database was prepared. Each Indian recipe references a unique expected JPG filename, but those files have not been supplied. The application shows an explicit local placeholder until the matching licensed photograph is added. No unrelated image is reused. Run `python scripts/validate_recipes.py` to regenerate `MISSING_PHOTOS.txt` with the full dish-to-filename list.\n',encoding='utf-8')
